def _features(ref, i):
    z = ref[..., i]
    return np.stack((np.ones_like(z), ref[..., 0], ref[..., 1], ref[..., 2], ref[..., 3], z * ref[..., (i + 1) % 4], z ** 3), axis=-1)

def _rosette_coefficients(ref, raw):
    clean = np.max(np.abs(raw), axis=1) < 7.0
    return np.array([np.linalg.lstsq(_features(ref[clean], i), raw[clean, i], rcond=None)[0] for i in range(4)])
